const categories = ['tools', 'garden', 'books'];
const items = [];
for (let i = 1; i <= 12; i++) {
  items.push({
    json: {
      orderId: 'ORD-' + String(i).padStart(3, '0'),
      category: categories[i % 3],
      qty: (i % 4) + 1,
      unitPrice: 10 * i + 0.99,
      status: i % 5 === 0 ? 'refunded' : 'paid'
    }
  });
}
return items;

const items = $input.all().map(i => i.json);
const byCat = {};
for (const it of items) {
  if (!byCat[it.category]) {
    byCat[it.category] = { orderCount: 0, totalRevenue: 0, refunded: 0 };
  }
  byCat[it.category].orderCount += 1;
  byCat[it.category].totalRevenue += it.lineTotal;
  if (it.status === 'refunded') {
    byCat[it.category].refunded += 1;
  }
}
return Object.entries(byCat).map(([category, s]) => ({
  json: {
    category,
    orderCount: s.orderCount,
    refundedCount: s.refunded,
    totalRevenue: Math.round(s.totalRevenue * 100) / 100,
    avgOrderValue: Math.round((s.totalRevenue / s.orderCount) * 100) / 100
  }
}));
